#!/usr/bin/env python3
"""Quarterly regional sales report.

Reads the quarterly CSV exports in ../data, normalises region spellings
(per data/regions.md), converts USD at the fixed 2026 rate (per data/fx.md)
and prints the JSON report defined in spec/report_format.md.

Standard library only. Deterministic: files are processed in sorted filename
order, output keys are sorted, and all arithmetic uses Decimal with
ROUND_HALF_UP rounding to 2 decimals at output time.
"""

import csv
import json
import re
import sys
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path

DATA_DIR = Path(__file__).resolve().parent.parent / "data"

# Fixed conversion rate for the whole of 2026 (data/fx.md). No live rates.
EUR_PER_USD = Decimal("0.92")

CENT = Decimal("0.01")

# Canonical region key -> accepted raw spellings (data/regions.md).
# Matching is exact (after stripping surrounding whitespace); any other
# spelling is counted under unknown_region, never silently dropped.
REGION_SPELLINGS = {
    "north": ["North", "NORTH", "n.", "Nord"],
    "south": ["South", "S.", "Sued"],
    "east": ["East", "E", "Ost"],
    "west": ["West", "W.", "Westen"],
    "central": ["Central", "Ctr", "Mitte"],
}
REGION_LOOKUP = {
    spelling: canonical
    for canonical, spellings in REGION_SPELLINGS.items()
    for spelling in spellings
}

QUARTER_FILE_RE = re.compile(r"sales_2026_(q[1-4])\.csv$")


def parse_qty(raw):
    """Return the quantity, or None if it is missing, non-numeric or negative."""
    if raw is None:
        return None
    raw = raw.strip()
    if not raw:
        return None
    try:
        qty = Decimal(raw)
    except InvalidOperation:
        return None
    if not qty.is_finite() or qty < 0:
        return None
    return qty


def row_revenue_eur(row):
    """Revenue for a valid row in EUR (qty * unit_price, USD converted)."""
    qty = parse_qty(row["qty"])
    if qty is None:
        return None
    try:
        price = Decimal(row["unit_price"].strip())
    except (InvalidOperation, AttributeError):
        return None
    currency = (row["currency"] or "").strip()
    if currency == "EUR":
        return qty * price
    if currency == "USD":
        return qty * price * EUR_PER_USD
    # Unknown currency: fail loudly rather than guess a rate.
    raise ValueError(
        "Unknown currency %r in order %r" % (currency, row.get("order_id"))
    )


def eur(value):
    return float(value.quantize(CENT, rounding=ROUND_HALF_UP))


def main():
    csv_paths = sorted(
        p for p in DATA_DIR.glob("sales_2026_q*.csv") if QUARTER_FILE_RE.search(p.name)
    )
    if not csv_paths:
        sys.exit("No quarterly exports found in %s" % DATA_DIR)

    totals_by_region = {key: Decimal("0") for key in REGION_SPELLINGS}
    totals_by_quarter = {}
    revenue_by_sku = {}
    rejected_rows = 0
    unknown_region = 0

    for path in csv_paths:
        quarter = QUARTER_FILE_RE.search(path.name).group(1)
        quarter_total = totals_by_quarter.setdefault(quarter, Decimal("0"))
        with path.open(newline="", encoding="utf-8") as fh:
            for row in csv.DictReader(fh):
                revenue = row_revenue_eur(row)
                if revenue is None:
                    rejected_rows += 1
                    continue
                region_key = REGION_LOOKUP.get((row["region"] or "").strip())
                if region_key is None:
                    unknown_region += 1
                else:
                    totals_by_region[region_key] += revenue
                quarter_total += revenue
                revenue_by_sku[row["sku"]] = (
                    revenue_by_sku.get(row["sku"], Decimal("0")) + revenue
                )
        totals_by_quarter[quarter] = quarter_total

    top_skus = sorted(revenue_by_sku.items(), key=lambda kv: (-kv[1], kv[0]))[:3]

    report = {
        "generated_for": "2026-Q1..Q3",
        "totals_by_region": {
            key: eur(totals_by_region[key]) for key in sorted(totals_by_region)
        },
        "totals_by_quarter": {
            key: eur(totals_by_quarter[key]) for key in sorted(totals_by_quarter)
        },
        "top_skus": [
            {"sku": sku, "revenue": eur(revenue)} for sku, revenue in top_skus
        ],
        "rejected_rows": rejected_rows,
        "unknown_region": unknown_region,
    }
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()
